ve.dm.MWReferenceNode.static.doReusesStoreBodyAlready = function ( dataElement, nodesWithSameKey ) {
    // Check if there are any nodes with the same key
    if ( nodesWithSameKey.length > 0 ) {
        // Iterate over each node with the same key
        for ( let i = 0; i < nodesWithSameKey.length; i++ ) {
            let node = nodesWithSameKey[i];
            // Check if the node's body already exists in the reuses store
            if ( node.body in ve.dm.MWReferenceNode.static.reusesStore ) {
                // If the body exists, reuse it
                dataElement.body = ve.dm.MWReferenceNode.static.reusesStore[node.body];
            } else {
                // If the body does not exist, store it
                ve.dm.MWReferenceNode.static.reusesStore[node.body] = node.body;
                dataElement.body = node.body;
            }
        }
    }
};
