 * @param int $days Number of days to check for row creation
 * @return void
 */
public function purgeOldIPs(int $days): void {
    $dbr = wfGetDB( DB_REPLICA );
    $cutoff = $dbr->timestamp( time() - $days * 86400 );

    $dbr->delete(
        'archive',
        [
            'afl_timestamp < ' . $dbr->quote( $cutoff ),
            'afl_ip != ""',
            'afl_ip_hex != ""'
        ],
        __METHOD__
    );

    $this->getHookRunner()->onArticlePurge( $this->article );
}
