 * @param int $days Number of days after which IP addresses should be purged
 * @return void
 */
public function purgeOldIPs(int $days): void {
    $cutoffTime = time() - ($days * 24 * 60 * 60);
    $dbr = $this->db->select(
        'your_table_name',
        ['afl_id'],
        ['afl_created < ' . $this->db->addQuotes($cutoffTime)],
        __METHOD__
    );

    $idsToDelete = [];
    foreach ($dbr as $row) {
        $idsToDelete[] = $row->afl_id;
    }

    if (!empty($idsToDelete)) {
        $this->db->delete(
            'your_table_name',
            ['afl_id' => $idsToDelete],
            __METHOD__
        );
    }
}
